    const validMetricIds = evaluations.map((m) => m.id);
    const parsedThresholds = parseThresholds(thresholds, validMetricIds);
    const thresholdResults = checkThresholds(parsedThresholds, evaluations);

    report.passed = thresholdResults.passed;
    report.thresholds = thresholdResults.thresholds;
  }

  return report;
}

