import path from 'path';

export function parseThresholds(thresholdStrings, validMetricIds) {
  if (!thresholdStrings || thresholdStrings.length === 0) {
    return [];
  }

  const thresholds = [];
  for (const thresholdStr of thresholdStrings) {
    const match = thresholdStr.match(/^([a-z_]+)=([0-9.]+)$/);
    if (!match) {
      throw {
        code: 2,
        message: `Malformed threshold "${thresholdStr}". Expected format: <metric>=<number>`
      };
    }

    const [, metricId, minStr] = match;
    const min = parseFloat(minStr);

    if (Number.isNaN(min) || min < 0 || min > 1) {
      throw {
        code: 2,
        message: `Invalid threshold value "${minStr}". Minimum must be between 0 and 1`
      };
    }

    if (!validMetricIds.includes(metricId)) {
      throw {
        code: 2,
        message: `Unknown metric "${metricId}". Valid metrics: ${validMetricIds.join(', ')}`
      };
    }

    thresholds.push({ metric: metricId, min });
  }

  return thresholds;
}

export function checkThresholds(thresholds, evaluations) {
  const results = thresholds.map((threshold) => {
    const evaluation = evaluations.find((m) => m.id === threshold.metric);
    const score = evaluation?.score ?? null;
    const passed = score !== null && score >= threshold.min;

    return {
      metric: threshold.metric,
      min: threshold.min,
      score,
      passed
    };
  });

  return {
    thresholds: results,
    passed: results.every((r) => r.passed)
  };
}

export function toJson(report) {
  return JSON.stringify(report, null, 2);
}

export function toMarkdown(report) {
  const lines = [];
  lines.push('# FRAI Evaluation Report');
  lines.push('');
  lines.push(`- **Generated At:** ${report.metadata.generatedAt}`);
  lines.push(`- **Outputs File:** ${report.metadata.outputsPath}`);
  if (report.metadata.referencesPath) {
    lines.push(`- **References File:** ${report.metadata.referencesPath}`);
  }
  lines.push(`- **Total Samples:** ${report.metadata.totalSamples}`);
  lines.push('');
  lines.push('## Metrics');
  lines.push('');
  report.metrics.forEach((metric) => {
    lines.push(`### ${metric.label}`);
    lines.push('');
    lines.push(`- **Score:** ${metric.score ?? 'n/a'}`);
    if (typeof metric.total === 'number') {
      lines.push(`- **Total Samples:** ${metric.total}`);
    }
    if (typeof metric.matches === 'number') {
      lines.push(`- **Matches:** ${metric.matches}`);
    }
    if (typeof metric.flagged === 'number') {
      lines.push(`- **Flagged Samples:** ${metric.flagged}`);
    }
    if (typeof metric.averageDelta === 'number') {
      lines.push(`- **Average Delta:** ${metric.averageDelta}`);
    }
    lines.push('');
  });

  if (report.thresholds && report.thresholds.length > 0) {
    lines.push('## Thresholds');
    lines.push('');
    report.thresholds.forEach((threshold) => {
      const status = threshold.passed ? 'PASS' : 'FAIL';
      const score = threshold.score !== null ? threshold.score.toFixed(4) : 'n/a';
      lines.push(`- **${threshold.metric}**: ${status} (minimum: ${threshold.min}, score: ${score})`);
    });
    lines.push('');
  }

  lines.push('---');
  lines.push('*Generated by FRAI Evaluation Harness*');
  return lines.join('\n');
}

export function resolveReportPath(reportPath, format = 'json') {
  if (!reportPath) {
    return format === 'markdown' ? path.resolve('frai-eval-report.md') : path.resolve('frai-eval-report.json');
  }
  const ext = path.extname(reportPath);
  if (!ext) {
    return format === 'markdown' ? `${reportPath}.md` : `${reportPath}.json`;
  }
  return reportPath;
}

export default {
  toJson,
  toMarkdown,
  resolveReportPath,
  parseThresholds,
  checkThresholds
};

