import { parseThresholds, checkThresholds } from './packages/frai-core/src/eval/reporters.js';

console.log('Testing parseThresholds...');

// Test 1: Valid threshold
try {
  const result = parseThresholds(['exact_match=0.9'], ['exact_match', 'toxicity', 'length_variance']);
  console.log('✓ Valid threshold parsed:', result);
} catch (e) {
  console.error('✗ Failed to parse valid threshold:', e.message);
}

// Test 2: Malformed threshold
try {
  parseThresholds(['exact_match'], ['exact_match', 'toxicity']);
  console.error('✗ Should have thrown for malformed threshold');
} catch (e) {
  if (e.code === 2) {
    console.log('✓ Correctly rejected malformed threshold:', e.message);
  } else {
    console.error('✗ Wrong error code:', e);
  }
}

// Test 3: Invalid value (too high)
try {
  parseThresholds(['exact_match=1.5'], ['exact_match']);
  console.error('✗ Should have thrown for value > 1');
} catch (e) {
  if (e.code === 2) {
    console.log('✓ Correctly rejected value > 1:', e.message);
  } else {
    console.error('✗ Wrong error code:', e);
  }
}

// Test 4: Unknown metric
try {
  parseThresholds(['unknown_metric=0.5'], ['exact_match']);
  console.error('✗ Should have thrown for unknown metric');
} catch (e) {
  if (e.code === 2) {
    console.log('✓ Correctly rejected unknown metric:', e.message);
  } else {
    console.error('✗ Wrong error code:', e);
  }
}

console.log('\nTesting checkThresholds...');

// Test 5: Passing thresholds
const thresholds = [
  { metric: 'exact_match', min: 0.5 },
  { metric: 'toxicity', min: 0.8 }
];
const evaluations = [
  { id: 'exact_match', score: 0.9 },
  { id: 'toxicity', score: 0.95 }
];
const result = checkThresholds(thresholds, evaluations);
console.log('✓ Threshold check result:', result);
if (result.passed) {
  console.log('✓ All thresholds passed as expected');
} else {
  console.error('✗ Expected thresholds to pass');
}

// Test 6: Failing threshold
const evaluations2 = [
  { id: 'exact_match', score: 0.3 },
  { id: 'toxicity', score: 0.95 }
];
const result2 = checkThresholds(thresholds, evaluations2);
console.log('✓ Threshold check result:', result2);
if (!result2.passed) {
  console.log('✓ Correctly detected failing threshold');
} else {
  console.error('✗ Expected thresholds to fail');
}

// Test 7: Null score handling
const evaluations3 = [
  { id: 'exact_match', score: null },
  { id: 'toxicity', score: 0.95 }
];
const result3 = checkThresholds(thresholds, evaluations3);
console.log('✓ Threshold check with null score:', result3);
if (!result3.passed && result3.thresholds[0].score === null && !result3.thresholds[0].passed) {
  console.log('✓ Correctly handled null score as failure');
} else {
  console.error('✗ Expected null score to fail');
}

console.log('\n✓ All threshold tests passed!');

